import { formatQuoteNumber } from './quote-number';
import { day } from '../../testing/clock';

/**
 * US-03-AC-10 / US-03-Q-07 (ADR-0008): the simulated quote number is
 * `COT-<country code>-<YYYYMMDD of today>-<6 digits>`. The date is the browser's local date, read
 * through the injectable clock by the caller; the digits come from an injectable source.
 *
 * Expected API (`frontend/src/app/shared/quote-number.ts`):
 *   formatQuoteNumber(countryCode: string, today: Date, digits: number): string
 */
describe('US-03-AC-10 simulated quote number', () => {
  const rows: [Date, string, number, string][] = [
    [day(2026, 11, 21), 'CO', 482913, 'COT-CO-20261121-482913'],
    [day(2026, 11, 21), 'CL', 7, 'COT-CL-20261121-000007'],
    [day(2027, 1, 5), 'CO', 999999, 'COT-CO-20270105-999999'],
  ];
  for (const [today, code, digits, expected] of rows) {
    it(`US-03-AC-10 ${code} on ${today.getFullYear()}-${today.getMonth() + 1}-${today.getDate()} with ${digits} gives ${expected}`, () => {
      expect(formatQuoteNumber(code, today, digits)).toBe(expected);
    });
  }

  it('US-03-AC-10 the digits are zero-padded to 6: 0 -> "000000", 12 -> "000012", 123456 stays', () => {
    expect(formatQuoteNumber('CO', day(2026, 11, 21), 0)).toBe('COT-CO-20261121-000000');
    expect(formatQuoteNumber('CO', day(2026, 11, 21), 12)).toBe('COT-CO-20261121-000012');
    expect(formatQuoteNumber('CO', day(2026, 11, 21), 123456)).toBe('COT-CO-20261121-123456');
  });

  it('US-03-AC-10 the country code is upper case, whatever case the caller holds', () => {
    expect(formatQuoteNumber('co', day(2026, 11, 21), 5)).toBe('COT-CO-20261121-000005');
  });

  it('US-03-AC-10 the date is the local calendar date: late in the evening it is still that day', () => {
    expect(formatQuoteNumber('CO', day(2026, 11, 21, 23, 59, 59), 1)).toBe('COT-CO-20261121-000001');
    expect(formatQuoteNumber('CO', day(2026, 12, 1, 0, 0, 1), 1)).toBe('COT-CO-20261201-000001');
  });

  it('US-03-AC-10 month and day are two digits, the year four: 2026-03-04', () => {
    expect(formatQuoteNumber('CL', day(2026, 3, 4), 42)).toBe('COT-CL-20260304-000042');
  });

  it('US-03-AC-10 the shape is always COT-<2 letters>-<8 digits>-<6 digits>', () => {
    for (const digits of [0, 1, 99, 100000, 999999]) {
      expect(formatQuoteNumber('CO', day(2026, 11, 21), digits)).toMatch(/^COT-[A-Z]{2}-\d{8}-\d{6}$/);
    }
  });
});
import { TestBed } from '@angular/core/testing';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { RANDOM_DIGITS } from './random-digits';

/**
 * ADR-0008 (US-03-Q-07): `RANDOM_DIGITS` is an `InjectionToken<() => number>` that returns an
 * integer in [0, 999 999]. The default uses `crypto.getRandomValues` on a `Uint32Array(1)` with
 * rejection sampling: a draw of 4 294 000 000 or more is discarded and drawn again, then the
 * value is taken modulo 1 000 000, so every result is equally likely.
 *
 * Expected API (`frontend/src/app/core/random-digits.ts`):
 *   RANDOM_DIGITS: InjectionToken<() => number>   with a root-provided default factory (as CLOCK)
 */
describe('US-03-AC-10 the default random source of the quote number', () => {
  let draw: ReturnType<typeof vi.spyOn>;

  /** Scripts the successive 32-bit values `crypto.getRandomValues` hands out. */
  function script(...values: number[]): void {
    const queue = [...values];
    draw.mockImplementation(((array: Uint32Array) => {
      array[0] = queue.length > 0 ? (queue.shift() as number) : 0;
      return array;
    }) as never);
  }
  const next = (): number => (TestBed.inject(RANDOM_DIGITS) as () => number)();

  beforeEach(() => {
    draw = vi.spyOn(globalThis.crypto, 'getRandomValues');
  });
  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('US-03-AC-10 a draw of 0 gives 0', () => {
    script(0);
    expect(next()).toBe(0);
  });

  it('US-03-AC-10 the value is the draw modulo 1 000 000 (123 456 789 -> 456 789)', () => {
    script(123_456_789);
    expect(next()).toBe(456_789);
  });

  it('US-03-AC-10 the largest accepted draw, 4 293 999 999, gives 999 999 (boundary, accepted)', () => {
    script(4_293_999_999);
    expect(next()).toBe(999_999);
  });

  it('US-03-AC-10 a draw of exactly 4 294 000 000 is discarded and drawn again (boundary, rejected)', () => {
    script(4_294_000_000, 123_456_789);
    expect(next()).toBe(456_789);
    expect(draw).toHaveBeenCalledTimes(2);
  });

  it('US-03-AC-10 every draw from 4 294 000 000 up to 4 294 967 295 is discarded, however many in a row', () => {
    script(4_294_967_295, 4_294_000_001, 4_294_500_000, 7);
    expect(next()).toBe(7);
    expect(draw).toHaveBeenCalledTimes(4);
  });

  it('US-03-AC-10 the source asks the platform for exactly one 32-bit value per draw (a Uint32Array of length 1)', () => {
    script(5);
    next();
    const array = (draw.mock.calls as unknown as Uint32Array[][])[0][0];
    expect(array).toBeInstanceOf(Uint32Array);
    expect(array.length).toBe(1);
  });

  it('US-03-AC-10 with the real platform source, 500 draws are all integers in [0, 999 999]', () => {
    draw.mockRestore();
    const random = TestBed.inject(RANDOM_DIGITS) as () => number;
    for (let i = 0; i < 500; i++) {
      const value = random();
      expect(Number.isInteger(value)).toBe(true);
      expect(value).toBeGreaterThanOrEqual(0);
      expect(value).toBeLessThanOrEqual(999_999);
    }
  });

  it('US-03-AC-10 a test can provide its own fixed source', () => {
    TestBed.configureTestingModule({ providers: [{ provide: RANDOM_DIGITS, useValue: () => 482_913 }] });
    expect(next()).toBe(482_913);
  });
});

