/** Typed field configuration (spec 7.1). Produced at the boundary by `parseFieldConfigs`. */
export type FieldType = 'text' | 'number' | 'select' | 'date' | 'checkbox';

export interface SelectOption {
  value: string;
  label: string;
  sortOrder: number;
}

export type ValidationRule = { message?: string } & (
  | { kind: 'minLength' | 'maxLength'; value: number }
  | { kind: 'min' | 'max'; value: number }
  | { kind: 'pattern'; value: string }
  | { kind: 'minAge'; years: number }
  | { kind: 'yearRange'; maxYearsOld: number; maxYearsAhead: number }
  | { kind: 'rutCheckDigit' }
);

export interface FieldConfig {
  key: string;
  type: FieldType;
  label: string;
  helpText?: string;
  placeholder?: string;
  isRequired: boolean;
  sortOrder: number;
  errorMessage: string;
  requiredMessage?: string;
  options?: SelectOption[];
  rules: ValidationRule[];
}

/** Value held by the editing model for one field: never null (ADR-0004). */
export type RawValue = string | boolean;
export type RawValues = Record<string, RawValue>;

/** Value of one field in the typed step 1 output (spec 7.3). */
export type OutputValue = string | number | boolean | null;

/** What step 1 hands to later steps (spec 7.3), produced only on a valid "Continuar". */
export interface Step1Output {
  country: string;
  values: Record<string, OutputValue>;
}
const formatters = new Map<string, Intl.NumberFormat>();

/**
 * A price in the country's currency (US-02-AC-06): `Intl.NumberFormat` currency style with the
 * country's `locale` and `currencyCode`, no fraction digits, grouping always on. Nothing here
 * knows a country; an invalid locale or currency makes `Intl` throw a `RangeError`, which the
 * caller turns into its error state.
 */
export function formatMoney(amount: number, locale: string, currencyCode: string): string {
  const cacheKey = `${locale}|${currencyCode}`;
  let formatter = formatters.get(cacheKey);
  if (!formatter) {
    // `useGrouping: 'always'` (ES2023.Intl typings, added to tsconfig `lib`): Spanish
    // locales would otherwise leave four-digit amounts ungrouped.
    const options: Intl.NumberFormatOptions = {
      style: 'currency',
      currency: currencyCode,
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
      useGrouping: 'always',
    };
    formatter = new Intl.NumberFormat(locale, options);
    formatters.set(cacheKey, formatter);
  }
  return formatter.format(amount);
}
